/**
 * @jest-environment node
 */

import { jest } from "@jest/globals";
import request from "supertest";
import express, { Express } from "express";
import cookieParser from "cookie-parser";
import paymentsRoutes from "../../routes/payments/index.js";
import {
  mockPrismaClient,
  mockRedisClient,
  createMockJWTPayload,
  createMockAuthMiddleware,
} from "../helpers/mock-helpers.js";

// Mock all dependencies BEFORE imports
jest.mock("../../config/database.js", () => ({
  prisma: mockPrismaClient,
}));

jest.mock("../../config/redis.js", () => ({
  redis: mockRedisClient,
}));

jest.mock("../../middleware/auth/auth.js", () => ({
  verifyToken: (req: any, res: any, next: any) => {
    if (!req.user) {
      return res.status(401).json({
        success: false,
        message: "Non authentifié",
      });
    }
    next();
  },
}));

describe("Payments Routes - Real Tests", () => {
  let app: Express;

  beforeAll(() => {
    app = express();
    app.use(express.json());
    app.use(cookieParser());

    // Add mock auth middleware
    app.use(createMockAuthMiddleware());

    app.use("/api/payments", paymentsRoutes);

    // Error handler
    app.use(
      (
        err: any,
        req: express.Request,
        res: express.Response,
        next: express.NextFunction,
      ) => {
        console.error("Test error:", err);
        res.status(500).json({ success: false, message: err.message });
      },
    );
  });

  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe("POST /api/payments/stripe/webhook", () => {
    it("should handle payment_intent.succeeded event", async () => {
      const webhookEvent = {
        type: "payment_intent.succeeded",
        data: {
          object: {
            id: "pi_123456",
            amount: 5000,
            currency: "eur",
            status: "succeeded",
          },
        },
      };

      const response = await request(app)
        .post("/api/payments/stripe/webhook")
        .send(webhookEvent)
        .expect(200);

      expect(response.body).toEqual({
        received: true,
      });
    });

    it("should handle payment_intent.payment_failed event", async () => {
      const webhookEvent = {
        type: "payment_intent.payment_failed",
        data: {
          object: {
            id: "pi_123456",
            amount: 5000,
            currency: "eur",
            status: "failed",
          },
        },
      };

      const response = await request(app)
        .post("/api/payments/stripe/webhook")
        .send(webhookEvent)
        .expect(200);

      expect(response.body).toEqual({
        received: true,
      });
    });

    it("should handle unhandled event types gracefully", async () => {
      const webhookEvent = {
        type: "customer.created",
        data: {
          object: {
            id: "cus_123456",
          },
        },
      };

      const response = await request(app)
        .post("/api/payments/stripe/webhook")
        .send(webhookEvent)
        .expect(200);

      expect(response.body).toEqual({
        received: true,
      });
    });

    it("should handle webhook errors", async () => {
      const response = await request(app)
        .post("/api/payments/stripe/webhook")
        .send("invalid json")
        .set("Content-Type", "application/json")
        .expect(400);

      // Express will handle malformed JSON
      expect(response.body.error).toBeDefined();
    });

    it("should accept empty webhook payload", async () => {
      const response = await request(app)
        .post("/api/payments/stripe/webhook")
        .send({})
        .expect(200);

      expect(response.body).toEqual({
        received: true,
      });
    });
  });

  describe("POST /api/payments/stripe/create-payment-intent", () => {
    it("should create payment intent successfully", async () => {
      const response = await request(app)
        .post("/api/payments/stripe/create-payment-intent")
        .send({
          amount: 5000,
          currency: "eur",
          paymentMethodId: "pm_card_visa",
        })
        .expect(200);

      expect(response.body.success).toBe(true);
      expect(response.body.paymentIntent).toMatchObject({
        id: expect.stringContaining("pi_"),
        amount: 5000,
        currency: "eur",
        status: "requires_confirmation",
        client_secret: expect.stringContaining("pi_"),
      });
    });

    it("should use default currency when not provided", async () => {
      const response = await request(app)
        .post("/api/payments/stripe/create-payment-intent")
        .send({
          amount: 5000,
          paymentMethodId: "pm_card_visa",
        })
        .expect(200);

      expect(response.body.success).toBe(true);
      expect(response.body.paymentIntent.currency).toBe("eur");
    });

    it("should return 400 when amount is missing", async () => {
      const response = await request(app)
        .post("/api/payments/stripe/create-payment-intent")
        .send({
          paymentMethodId: "pm_card_visa",
        })
        .expect(400);

      expect(response.body).toEqual({
        success: false,
        message: "Montant et méthode de paiement requis",
      });
    });

    it("should return 400 when payment method is missing", async () => {
      const response = await request(app)
        .post("/api/payments/stripe/create-payment-intent")
        .send({
          amount: 5000,
        })
        .expect(400);

      expect(response.body).toEqual({
        success: false,
        message: "Montant et méthode de paiement requis",
      });
    });

    it("should handle different currencies", async () => {
      const response = await request(app)
        .post("/api/payments/stripe/create-payment-intent")
        .send({
          amount: 10000,
          currency: "usd",
          paymentMethodId: "pm_card_visa",
        })
        .expect(200);

      expect(response.body.success).toBe(true);
      expect(response.body.paymentIntent.currency).toBe("usd");
    });

    it("should handle zero amount", async () => {
      const response = await request(app)
        .post("/api/payments/stripe/create-payment-intent")
        .send({
          amount: 0,
          paymentMethodId: "pm_card_visa",
        })
        .expect(400);

      expect(response.body.success).toBe(false);
    });

    it("should handle negative amount", async () => {
      const response = await request(app)
        .post("/api/payments/stripe/create-payment-intent")
        .send({
          amount: -5000,
          paymentMethodId: "pm_card_visa",
        })
        .expect(400);

      expect(response.body.success).toBe(false);
    });

    it("should create unique payment intents", async () => {
      const response1 = await request(app)
        .post("/api/payments/stripe/create-payment-intent")
        .send({
          amount: 5000,
          paymentMethodId: "pm_card_visa",
        })
        .expect(200);

      const response2 = await request(app)
        .post("/api/payments/stripe/create-payment-intent")
        .send({
          amount: 5000,
          paymentMethodId: "pm_card_visa",
        })
        .expect(200);

      expect(response1.body.paymentIntent.id).not.toBe(
        response2.body.paymentIntent.id,
      );
    });
  });

  describe("POST /api/payments/stripe/confirm-payment", () => {
    it("should confirm payment successfully", async () => {
      const response = await request(app)
        .post("/api/payments/stripe/confirm-payment")
        .send({
          paymentIntentId: "pi_123456",
        })
        .expect(200);

      expect(response.body).toEqual({
        success: true,
        payment: {
          id: "pi_123456",
          status: "succeeded",
          amount_received: 100,
        },
      });
    });

    it("should return 400 when payment intent ID is missing", async () => {
      const response = await request(app)
        .post("/api/payments/stripe/confirm-payment")
        .send({})
        .expect(400);

      expect(response.body).toEqual({
        success: false,
        message: "ID intention de paiement requis",
      });
    });

    it("should handle different payment intent IDs", async () => {
      const testIds = ["pi_abc123", "pi_xyz789", "pi_test"];

      for (const id of testIds) {
        const response = await request(app)
          .post("/api/payments/stripe/confirm-payment")
          .send({
            paymentIntentId: id,
          })
          .expect(200);

        expect(response.body.payment.id).toBe(id);
        expect(response.body.payment.status).toBe("succeeded");
      }
    });

    it("should handle empty payment intent ID", async () => {
      const response = await request(app)
        .post("/api/payments/stripe/confirm-payment")
        .send({
          paymentIntentId: "",
        })
        .expect(400);

      expect(response.body.success).toBe(false);
    });
  });

  describe("GET /api/payments/subscriptions", () => {
    it("should get user subscriptions successfully", async () => {
      const response = await request(app)
        .get("/api/payments/subscriptions")
        .set("x-mock-user-id", "1")
        .set("x-mock-tenant-id", "1")
        .expect(200);

      expect(response.body.success).toBe(true);
      expect(response.body.data).toBeInstanceOf(Array);
      expect(response.body.data.length).toBeGreaterThan(0);
      expect(response.body.data[0]).toMatchObject({
        id: expect.any(Number),
        name: expect.any(String),
        price: expect.any(Number),
        status: expect.any(String),
        startDate: expect.any(String),
        endDate: expect.any(String),
      });
    });

    it("should return 401 when not authenticated", async () => {
      const response = await request(app)
        .get("/api/payments/subscriptions")
        .expect(401);

      expect(response.body).toEqual({
        success: false,
        message: "Non authentifié",
      });
    });

    it("should handle different user IDs", async () => {
      const response1 = await request(app)
        .get("/api/payments/subscriptions")
        .set("x-mock-user-id", "1")
        .set("x-mock-tenant-id", "1")
        .expect(200);

      const response2 = await request(app)
        .get("/api/payments/subscriptions")
        .set("x-mock-user-id", "2")
        .set("x-mock-tenant-id", "1")
        .expect(200);

      expect(response1.body.success).toBe(true);
      expect(response2.body.success).toBe(true);
    });
  });

  describe("POST /api/payments/subscriptions", () => {
    it("should create subscription successfully", async () => {
      const response = await request(app)
        .post("/api/payments/subscriptions")
        .set("x-mock-user-id", "1")
        .set("x-mock-tenant-id", "1")
        .send({
          planId: "plan_monthly",
          paymentMethodId: "pm_card_visa",
        })
        .expect(201);

      expect(response.body).toEqual({
        success: true,
        message: "Abonnement créé avec succès",
        data: {
          id: expect.any(Number),
          userId: 1,
          planId: "plan_monthly",
          status: "active",
          createdAt: expect.any(String),
        },
      });
    });

    it("should return 401 when not authenticated", async () => {
      const response = await request(app)
        .post("/api/payments/subscriptions")
        .send({
          planId: "plan_monthly",
          paymentMethodId: "pm_card_visa",
        })
        .expect(401);

      expect(response.body).toEqual({
        success: false,
        message: "Non authentifié",
      });
    });

    it("should return 400 when plan ID is missing", async () => {
      const response = await request(app)
        .post("/api/payments/subscriptions")
        .set("x-mock-user-id", "1")
        .set("x-mock-tenant-id", "1")
        .send({
          paymentMethodId: "pm_card_visa",
        })
        .expect(400);

      expect(response.body).toEqual({
        success: false,
        message: "Plan et méthode de paiement requis",
      });
    });

    it("should return 400 when payment method is missing", async () => {
      const response = await request(app)
        .post("/api/payments/subscriptions")
        .set("x-mock-user-id", "1")
        .set("x-mock-tenant-id", "1")
        .send({
          planId: "plan_monthly",
        })
        .expect(400);

      expect(response.body).toEqual({
        success: false,
        message: "Plan et méthode de paiement requis",
      });
    });

    it("should handle different plan types", async () => {
      const plans = ["plan_monthly", "plan_yearly", "plan_premium"];

      for (const planId of plans) {
        const response = await request(app)
          .post("/api/payments/subscriptions")
          .set("x-mock-user-id", "1")
          .set("x-mock-tenant-id", "1")
          .send({
            planId,
            paymentMethodId: "pm_card_visa",
          })
          .expect(201);

        expect(response.body.data.planId).toBe(planId);
      }
    });

    it("should create unique subscription IDs", async () => {
      const response1 = await request(app)
        .post("/api/payments/subscriptions")
        .set("x-mock-user-id", "1")
        .set("x-mock-tenant-id", "1")
        .send({
          planId: "plan_monthly",
          paymentMethodId: "pm_card_visa",
        })
        .expect(201);

      // Small delay to ensure different timestamps
      await new Promise((resolve) => setTimeout(resolve, 10));

      const response2 = await request(app)
        .post("/api/payments/subscriptions")
        .set("x-mock-user-id", "1")
        .set("x-mock-tenant-id", "1")
        .send({
          planId: "plan_monthly",
          paymentMethodId: "pm_card_visa",
        })
        .expect(201);

      expect(response1.body.data.id).not.toBe(response2.body.data.id);
    });
  });

  describe("PUT /api/payments/subscriptions/:id/cancel", () => {
    it("should cancel subscription successfully", async () => {
      const response = await request(app)
        .put("/api/payments/subscriptions/1/cancel")
        .set("x-mock-user-id", "1")
        .set("x-mock-tenant-id", "1")
        .expect(200);

      expect(response.body).toEqual({
        success: true,
        message: "Abonnement annulé avec succès",
      });
    });

    it("should return 401 when not authenticated", async () => {
      const response = await request(app)
        .put("/api/payments/subscriptions/1/cancel")
        .expect(401);

      expect(response.body).toEqual({
        success: false,
        message: "Non authentifié",
      });
    });

    it("should handle different subscription IDs", async () => {
      const subscriptionIds = [1, 2, 999];

      for (const id of subscriptionIds) {
        const response = await request(app)
          .put(`/api/payments/subscriptions/${id}/cancel`)
          .set("x-mock-user-id", "1")
          .set("x-mock-tenant-id", "1")
          .expect(200);

        expect(response.body.success).toBe(true);
      }
    });

    it("should handle invalid subscription ID format", async () => {
      const response = await request(app)
        .put("/api/payments/subscriptions/invalid/cancel")
        .set("x-mock-user-id", "1")
        .set("x-mock-tenant-id", "1")
        .expect(200);

      // Still succeeds in mock implementation
      expect(response.body.success).toBe(true);
    });
  });

  describe("Edge Cases & Security", () => {
    it("should handle malformed JSON in payment intent creation", async () => {
      const response = await request(app)
        .post("/api/payments/stripe/create-payment-intent")
        .set("Content-Type", "application/json")
        .send("{ invalid json }")
        .expect(400);

      expect(response.body.success).toBe(false);
    });

    it("should handle very large payment amounts", async () => {
      const response = await request(app)
        .post("/api/payments/stripe/create-payment-intent")
        .send({
          amount: Number.MAX_SAFE_INTEGER,
          paymentMethodId: "pm_card_visa",
        })
        .expect(200);

      expect(response.body.success).toBe(true);
      expect(response.body.paymentIntent.amount).toBe(Number.MAX_SAFE_INTEGER);
    });

    it("should handle special characters in payment method ID", async () => {
      const response = await request(app)
        .post("/api/payments/stripe/create-payment-intent")
        .send({
          amount: 5000,
          paymentMethodId: "pm_test_!@#$%",
        })
        .expect(200);

      expect(response.body.success).toBe(true);
    });

    it("should handle concurrent payment intent creations", async () => {
      const requests = Array(10)
        .fill(null)
        .map(() =>
          request(app).post("/api/payments/stripe/create-payment-intent").send({
            amount: 5000,
            paymentMethodId: "pm_card_visa",
          }),
        );

      const responses = await Promise.all(requests);

      responses.forEach((response) => {
        expect(response.status).toBe(200);
        expect(response.body.success).toBe(true);
      });

      // All payment intents should have unique IDs
      const ids = responses.map((r) => r.body.paymentIntent.id);
      const uniqueIds = new Set(ids);
      expect(uniqueIds.size).toBe(ids.length);
    });

    it("should handle concurrent subscription creations", async () => {
      const requests = Array(5)
        .fill(null)
        .map((_, i) =>
          request(app)
            .post("/api/payments/subscriptions")
            .set("x-mock-user-id", `${i + 1}`)
            .set("x-mock-tenant-id", "1")
            .send({
              planId: "plan_monthly",
              paymentMethodId: "pm_card_visa",
            }),
        );

      const responses = await Promise.all(requests);

      responses.forEach((response) => {
        expect(response.status).toBe(201);
        expect(response.body.success).toBe(true);
      });
    });

    it("should handle webhook with missing data field", async () => {
      const webhookEvent = {
        type: "payment_intent.succeeded",
        // Missing data field
      };

      const response = await request(app)
        .post("/api/payments/stripe/webhook")
        .send(webhookEvent)
        .expect(200);

      expect(response.body).toEqual({
        received: true,
      });
    });

    it("should handle webhook with null event type", async () => {
      const webhookEvent = {
        type: null,
        data: {
          object: {},
        },
      };

      const response = await request(app)
        .post("/api/payments/stripe/webhook")
        .send(webhookEvent)
        .expect(200);

      expect(response.body).toEqual({
        received: true,
      });
    });

    it("should handle subscription cancellation race conditions", async () => {
      const requests = Array(3)
        .fill(null)
        .map(() =>
          request(app)
            .put("/api/payments/subscriptions/1/cancel")
            .set("x-mock-user-id", "1")
            .set("x-mock-tenant-id", "1"),
        );

      const responses = await Promise.all(requests);

      responses.forEach((response) => {
        expect(response.status).toBe(200);
        expect(response.body.success).toBe(true);
      });
    });

    it("should handle payment confirmation with long payment intent ID", async () => {
      const longId = "pi_" + "x".repeat(1000);

      const response = await request(app)
        .post("/api/payments/stripe/confirm-payment")
        .send({
          paymentIntentId: longId,
        })
        .expect(200);

      expect(response.body.success).toBe(true);
      expect(response.body.payment.id).toBe(longId);
    });

    it("should handle subscription with special characters in plan ID", async () => {
      const response = await request(app)
        .post("/api/payments/subscriptions")
        .set("x-mock-user-id", "1")
        .set("x-mock-tenant-id", "1")
        .send({
          planId: "plan-test_123-special!",
          paymentMethodId: "pm_card_visa",
        })
        .expect(201);

      expect(response.body.success).toBe(true);
      expect(response.body.data.planId).toBe("plan-test_123-special!");
    });

    it("should handle payment with different currencies", async () => {
      const currencies = ["eur", "usd", "gbp", "jpy"];

      for (const currency of currencies) {
        const response = await request(app)
          .post("/api/payments/stripe/create-payment-intent")
          .send({
            amount: 5000,
            currency,
            paymentMethodId: "pm_card_visa",
          })
          .expect(200);

        expect(response.body.paymentIntent.currency).toBe(currency);
      }
    });
  });
});
